WITH recent_departments AS (SELECT * FROM departments WHERE location IN ('London', 'Chiang Mai')), location_summary AS (SELECT location, CASE WHEN budget >= 3989000 THEN 'high' WHEN budget >= 1895000 THEN 'mid' ELSE 'low' END AS budget_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(dept_name))) AS dept_name_values, COUNT(DISTINCT budget) AS unique_locations FROM recent_departments GROUP BY location, CASE WHEN budget >= 3989000 THEN 'high' WHEN budget >= 1895000 THEN 'mid' ELSE 'low' END) SELECT location, budget_bucket, dept_name_values FROM location_summary WHERE unique_locations > 8 ORDER BY dept_name_values, location DESC;
